mapper.select:
SELECT id, conversation_id, user_id, role, content, status, trace_id, finish_reason, error_message, create_time
FROM sa_message
WHERE conversation_id = #{conversationId} AND user_id = #{userId}
AND id < #{beforeId}
ORDER BY id DESC
LIMIT #{limit}

mapper.update:
UPDATE sa_message SET status = 'CANCELLED', finish_reason = 'cancelled'
WHERE conversation_id = #{conversationId} AND user_id = #{userId}
  AND trace_id = #{traceId} AND status = 'GENERATING'
